<?php
declare(strict_types=1);
require __DIR__ . '/config.php';require __DIR__ . '/helpers.php';
$orderId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$orderId)redirect('credits.php');
$stmt=$pdo->prepare("SELECT o.*,t.table_no FROM orders o JOIN cafe_tables t ON t.id=o.table_id WHERE o.id=? AND o.status='credit' LIMIT 1");$stmt->execute([$orderId]);$credit=$stmt->fetch();if(!$credit){http_response_code(404);exit('Açık veresiye bulunamadı.');}
$profile=business_profile($pdo);$categories=active_categories($pdo);$products=active_products($pdo);$state=order_payload_by_order_id($pdo,(int)$orderId);$csrf=csrf_token();$date=$credit['credit_created_at']?:$credit['opened_at'];
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= e($csrf) ?>"><title><?= e((string)$credit['credit_name']) ?> • Veresiye</title><?php if($profile['logo_path']!==''):?><link rel="icon" href="<?= e($profile['logo_path']) ?>"><?php endif;?><link rel="stylesheet" href="assets/style.css?v=10.1"></head><body><header class="topbar"><div class="container topbar-inner"><a class="brand" href="credits.php"><?php if($profile['logo_path']!==''):?><span class="brand-mark brand-mark-image"><img src="<?= e($profile['logo_path']) ?>" alt="Logo"></span><?php else:?><span class="brand-mark"><?= e(business_initials($profile['name'])) ?></span><?php endif;?><span><?= e($profile['name']) ?><small>Veresiye #<?= (int)$orderId ?></small></span></a><div class="nav-actions"><a class="btn btn-ghost" href="credits.php">← Veresiyeler</a><a class="btn btn-ghost" href="orders.php">Adisyonlar</a><a class="btn btn-ghost" href="home.php">Masalar</a></div></div></header>
<main class="order-layout credit-order-layout"><section class="menu-panel"><div class="panel credit-profile"><div><div class="eyebrow">Açık Veresiye</div><h1><?= e((string)($credit['credit_name']?:'İsimsiz Veresiye')) ?></h1><p><?= e(relative_time_tr($date)) ?> • <?= e(date('d.m.Y H:i',strtotime($date))) ?> • İlk açıldığı masa: <?= (int)$credit['table_no'] ?></p></div><button class="btn" type="button" id="editMetaBtn">Bilgileri Düzenle</button></div><div class="panel menu-toolbar"><div><div class="eyebrow">Veresiyeye Ekle</div><h2>Ürünler</h2><p class="muted">Bu hesaba sonradan ürün veya özel kalem ekleyebilirsiniz.</p></div><label class="search-box">Ürün ara<input type="search" id="productSearch" placeholder="Ürün ara..."></label></div><div class="table-action-bar panel"><button class="btn btn-primary" id="customBtn">+ Bonus / Özel Kalem</button></div><div class="category-tabs" id="categoryTabs"><button class="category-tab active" data-category="all">Tümü</button><?php foreach($categories as $c):?><button class="category-tab" data-category="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></button><?php endforeach;?></div><div class="product-grid" id="productGrid"><?php foreach($products as $p):?><article class="product-card" data-category="<?= (int)$p['category_id'] ?>" data-search="<?= e($p['name'].' '.($p['description']??'').' '.$p['category_name']) ?>"><div><div class="product-name"><?= e($p['name']) ?></div><?php if(!empty($p['description'])):?><div class="product-description"><?= e($p['description']) ?></div><?php endif;?><div class="product-category"><?= e($p['category_name']) ?></div></div><div class="product-bottom"><div class="price"><?= money((float)$p['price']) ?></div><button class="add-btn" data-product-id="<?= (int)$p['id'] ?>">+</button></div></article><?php endforeach;?></div></section>
<aside class="receipt"><div class="receipt-head"><div><div class="eyebrow">Veresiye Adisyonu</div><h2>#<?= (int)$orderId ?></h2></div><span class="badge gold" id="itemCountBadge">0 ürün</span></div><div class="receipt-body" id="receiptBody"></div><div class="receipt-foot"><div class="totals-breakdown"><div class="grand-total"><span>Toplam alacak</span><strong id="totalValue">0,00 ₺</strong></div></div><div class="payment-box"><span>Ödeme alındığında</span><div class="payment-options"><label><input type="radio" name="paymentMethod" value="cash" checked><span>Nakit</span></label><label><input type="radio" name="paymentMethod" value="card"><span>Kart</span></label><label><input type="radio" name="paymentMethod" value="other"><span>Diğer</span></label></div></div><button class="btn btn-success checkout" id="payBtn">Ödendi / Hesabı Kapat</button></div></aside></main>
<dialog class="app-dialog" id="metaDialog"><form method="dialog" class="dialog-card" id="metaForm"><div class="dialog-head"><div><div class="eyebrow">Veresiye Bilgisi</div><h3>Düzenle</h3></div><button type="button" class="dialog-close" data-close>×</button></div><label>Ad / kişi<input id="metaName" value="<?= e((string)$credit['credit_name']) ?>" required></label><label>Not<textarea id="metaNote"><?= e((string)($credit['credit_note']??'')) ?></textarea></label><div class="dialog-actions"><button type="button" class="btn btn-ghost" data-close>Vazgeç</button><button class="btn btn-primary">Kaydet</button></div></form></dialog>
<dialog class="app-dialog" id="customDialog"><form method="dialog" class="dialog-card" id="customForm"><div class="dialog-head"><div><div class="eyebrow">Özel Kalem</div><h3>Veresiyeye ekle</h3></div><button type="button" class="dialog-close" data-close>×</button></div><label>Başlık<input id="customName" placeholder="Örn. Servis ücreti" required></label><label>Tutar<input id="customPrice" type="number" min="0" step="0.01" required></label><label>Not<textarea id="customNote"></textarea></label><div class="dialog-actions"><button type="button" class="btn btn-ghost" data-close>Vazgeç</button><button class="btn btn-primary">Ekle</button></div></form></dialog>
<script src="assets/app.js?v=10"></script><script>
const orderId=<?= (int)$orderId ?>,csrf=document.querySelector('meta[name="csrf-token"]').content;let state=<?= json_encode($state,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,selectedCategory='all';function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));}async function post(url,p){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(p)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'İşlem başarısız.');return d;}function render(){document.getElementById('itemCountBadge').textContent=`${state.item_count||0} ürün`;document.getElementById('totalValue').textContent=formatMoney(state.subtotal||0);document.getElementById('payBtn').disabled=!state.items?.length;const b=document.getElementById('receiptBody');if(!state.items?.length){b.innerHTML='<div class="empty-receipt"><strong>Veresiye boş</strong></div>';return;}b.innerHTML=state.items.map(i=>`<div class="receipt-row"><div><div class="receipt-title">${esc(i.product_name)}</div><div class="receipt-sub">${i.quantity} × ${formatMoney(i.unit_price)}</div>${i.note?`<div class="item-note">📝 ${esc(i.note)}</div>`:''}<div class="qty-controls"><button class="qty-btn" data-remove="${i.id}">−</button><span>${i.quantity}</span>${i.product_id?`<button class="qty-btn" data-add="${i.product_id}">+</button>`:''}<button class="mini-action" data-note="${i.id}">Not</button></div></div><strong>${formatMoney(i.line_total)}</strong></div>`).join('');}
async function add(pid){try{const d=await post('api/credit_add_item.php',{order_id:orderId,product_id:Number(pid)});state=d.order;render();}catch(e){showToast(e.message,'error');}}document.querySelectorAll('.add-btn').forEach(b=>b.onclick=()=>add(b.dataset.productId));document.getElementById('receiptBody').addEventListener('click',async e=>{const a=e.target.closest('[data-add]');if(a)return add(a.dataset.add);const r=e.target.closest('[data-remove]');if(r){try{const d=await post('api/credit_remove_item.php',{order_id:orderId,item_id:Number(r.dataset.remove)});state=d.order;render();}catch(err){showToast(err.message,'error');}return;}const n=e.target.closest('[data-note]');if(n){const item=state.items.find(x=>x.id===Number(n.dataset.note));const note=prompt('Ürün notu:',item?.note||'');if(note===null)return;try{const d=await post('api/credit_update_item_note.php',{order_id:orderId,item_id:Number(n.dataset.note),note});state=d.order;render();}catch(err){showToast(err.message,'error');}}});function filter(){const q=document.getElementById('productSearch').value.trim().toLocaleLowerCase('tr-TR');document.querySelectorAll('.product-card').forEach(c=>c.style.display=((selectedCategory==='all'||c.dataset.category===selectedCategory)&&(!q||c.dataset.search.toLocaleLowerCase('tr-TR').includes(q)))?'':'none');}document.getElementById('categoryTabs').onclick=e=>{const b=e.target.closest('.category-tab');if(!b)return;document.querySelectorAll('.category-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedCategory=b.dataset.category;filter();};document.getElementById('productSearch').oninput=filter;document.getElementById('customBtn').onclick=()=>document.getElementById('customDialog').showModal();document.getElementById('editMetaBtn').onclick=()=>document.getElementById('metaDialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.getElementById('customForm').onsubmit=async e=>{e.preventDefault();try{const d=await post('api/credit_custom_item.php',{order_id:orderId,name:document.getElementById('customName').value,price:document.getElementById('customPrice').value,note:document.getElementById('customNote').value});state=d.order;render();document.getElementById('customDialog').close();e.target.reset();}catch(err){showToast(err.message,'error');}};document.getElementById('metaForm').onsubmit=async e=>{e.preventDefault();try{await post('api/credit_update_meta.php',{order_id:orderId,credit_name:document.getElementById('metaName').value,credit_note:document.getElementById('metaNote').value});showToast('Veresiye bilgileri güncellendi.');document.getElementById('metaDialog').close();setTimeout(()=>location.reload(),350);}catch(err){showToast(err.message,'error');}};document.getElementById('payBtn').onclick=async()=>{const payment=document.querySelector('input[name="paymentMethod"]:checked').value;if(!confirm(`${formatMoney(state.subtotal||0)} tutarındaki veresiye ödendi olarak kapatılsın mı?`))return;try{const d=await post('api/credit_pay.php',{order_id:orderId,payment_method:payment});showToast(`Veresiye kapatıldı: ${formatMoney(d.total)}`);setTimeout(()=>location.href='credits.php',500);}catch(err){showToast(err.message,'error');}};render();
</script></body></html>
